// 文件处理相关方法
const isImageFile = (file) => {
  const fileType = file.type || "";
  return ALLOWED_FILE_TYPES.IMAGE.includes(fileType);
};

const isSupportedFile = (file) => {
  const fileType = file.type || "";
  return ALLOWED_FILE_TYPES.DOCUMENT.includes(fileType);
};

// 获取文件在原始数组中的索引
const getFileIndex = (file) => {
  return uploadFiles.value.findIndex((f) => f.id === file.id);
};

// 获取图片在预览数组中的下标
const getImagePreviewIndex = (uploadFileIndex) => {
  return uploadToImageIndexMap.value.get(uploadFileIndex) || 0;
};

// 文件上传相关
const fileInputRef = ref(null);

// 计算可接受的文件类型字符串
const acceptedFileTypes = computed(() => {
  return [...ALLOWED_FILE_TYPES.IMAGE, ...ALLOWED_FILE_TYPES.DOCUMENT].join(
    ","
  );
});

// 计算还可以上传的文件数量
const maxFilesToUpload = computed(() => {
  return Math.max(0, 10 - uploadFiles.value.length);
});

// 处理上传文件按钮点击
const handleUploadFile = () => {
  dropdownRef.value.handleClose();
  if (maxFilesToUpload.value <= 0) {
    ElMessage.warning(t("maxFilesReached", { max: 10 }));
    return;
  }
  fileInputRef.value.click();
};

// 文件选择后的处理
const onFileSelected = (event) => {
  const files = event.target.files;
  if (!files || files.length === 0) return;

  // 检查文件数量限制
  const filesToProcess = Array.from(files).slice(0, maxFilesToUpload.value);

  if (filesToProcess.length < files.length) {
    ElMessage.warning(t("someFilesSkipped"));
  }

  // 处理每个文件
  filesToProcess.forEach((file) => {
    // 检查文件类型
    if (!isImageFile(file) && !isSupportedFile(file)) {
      ElMessage.error(t("fileTypeNotAllowedWithName", { name: file.name }));
      return;
    }

    // 创建文件对象
    const fileObj = {
      id: Date.now(),
      name: file.name,
      type: file.type,
      size: file.size,
      file: file,
      isLoading: true,
    };

    // 如果是图片，创建预览URL
    if (isImageFile(file)) {
      fileObj.previewUrl = URL.createObjectURL(file);
    }

    // 添加到上传列表
    addFileToUploadList(fileObj);

    // 真实文件上传过程
    realFileUpload(fileObj);
  });

  // 重置文件输入，以便可以再次选择相同的文件
  event.target.value = "";
};

// 添加文件到上传列表
const addFileToUploadList = (fileObj) => {
  const updatedFiles = [...uploadFiles.value];
  updatedFiles.push(fileObj);
  uploadFiles.value = updatedFiles;

  // 更新图片数组和映射关系
  updateImageFilesAndMapping();
};

// 真实文件上传过程
const realFileUpload = async (fileObj) => {
  try {
    let uploadResult;

    // 根据文件类型选择上传方法
    if (isImageFile(fileObj)) {
      // 如果是图片，传递尺寸信息
      const dimensions = fileObj.previewUrl ? await getImageDimensions(fileObj.previewUrl) : null;
      uploadResult = await uploadImage(fileObj.file, true, dimensions);
    } else {
      // 如果是文档
      uploadResult = await uploadDocument(fileObj.file);
      // uploadResult = {
      //   url: fileObj.url,
      //   name: fileObj.name,
      //   type: fileObj.type,
      //   size: fileObj.size,
      // };
    }

    const index = getFileIndex(fileObj);
    if (index !== -1) {
      // 更新文件状态为上传完成
      const updatedFiles = [...uploadFiles.value];
      updatedFiles[index].isLoading = false;
      updatedFiles[index].url = uploadResult.url;
      updatedFiles[index].mediaId = uploadResult.mediaId;
      uploadFiles.value = updatedFiles;

      // 更新图片数组和映射关系
      updateImageFilesAndMapping();

      // 添加到最近文件列表（已隐藏）
      // addFileToRecent(updatedFiles[index]);
    }
  } catch (error) {
    console.error('File upload failed:', error);

    const index = getFileIndex(fileObj);
    if (index !== -1) {
      // 上传失败，移除文件
      const updatedFiles = [...uploadFiles.value];
      updatedFiles.splice(index, 1);
      uploadFiles.value = updatedFiles;

      // 更新图片数组和映射关系
      updateImageFilesAndMapping();
    }

    // 显示错误消息
    ElMessage.error(t('uploadFailed'));
  }
};

// 添加文件到最近列表（已隐藏）
// const addFileToRecent = (file) => {
//   // 创建不包含file属性的副本
//   const fileForRecent = {
//     id: file.id,
