//   // 检查文件是否已存在
//   const existingIndex = recentFiles.value.findIndex(
//     (f) => f.name === file.name && f.size === file.size
//   );

//   // 更新recentFiles引用
//   const updatedFiles = [...recentFiles.value];

//   if (existingIndex !== -1) {
