//   }

//   // 更新本地引用和全局存储
//   recentFiles.value = updatedFiles;
//   app?.config?.globalProperties?.$recentFiles?.set(updatedFiles);
// };

// 处理文件删除
const handleDeleteFile = (index) => {
  // 如果是图片且有预览URL，释放内存
  if (
    uploadFiles.value[index] &&
    uploadFiles.value[index].previewUrl &&
    isImageFile(uploadFiles.value[index])
  ) {
    URL.revokeObjectURL(uploadFiles.value[index].previewUrl);
  }

  // 删除文件
  const updatedFiles = [...uploadFiles.value];
  updatedFiles.splice(index, 1);
  uploadFiles.value = updatedFiles;

  // 更新图片数组和映射关系
  updateImageFilesAndMapping();
};
// 更新图片数组和映射关系
const updateImageFilesAndMapping = () => {
    const newImageFiles = [];
    const newMapping = new Map();

    uploadFiles.value.forEach((file, uploadIndex) => {
        if (isImageFile(file)) {
            const imageIndex = newImageFiles.length;
            newImageFiles.push(file);
            newMapping.set(uploadIndex, imageIndex);
        }
    });

    imageFiles.value = newImageFiles;
    uploadToImageIndexMap.value = newMapping;
};
const inputStyle = computed(() => {
  const rawStyle = {
    color: "var(--text-title)",
    "font-size": "16px",
    "min-height": "70px !important",
    padding: "0",
    border: "none",
    "box-shadow": "none",
    "background-color": "transparent",
    "margin-bottom": "12px",
  };
  return convertStyleObject(rawStyle);
});

const getFileIcon = (file) => {
  const type = file.type || "";
  return FILE_ICON_MAP[type] || "/static/images/error_file_icon.png";
};

const deepSearchText = computed(() => {
  return t("deepSearch");
});

const deepSearchSrc = computed(() => {
  if (isSearchModeChoose.value) {
    return "/static/images/conversation/search_icon_selected.png";
  }
  return "/static/images/conversation/search_icon.png";
});

// 根据思考状态返回不同的图标
const getThinkIconSrc = computed(() => {
  return isThinking.value
    ? "/static/images/conversation/think_icon_s.png"
    : "/static/images/conversation/think_icon.png";
});

const deepSearchTooltipText = computed(() => {
  return t("advancedSearch");
});

const clickSelectSearchMode = () => {
  isSearchModeChoose.value = !isSearchModeChoose.value;

  // 如果选择了搜索模式，取消Think模式（互斥）
  if (isSearchModeChoose.value && isThinking.value) {
    isThinking.value = false;
  }

  console.log('isSearchModeChoose', isSearchModeChoose.value);

  // 更新aiChatStore中的搜索状态
  const currentParams = aiChatStore.getAIChatParams() || {};
  aiChatStore.setAIChatParams({
    ...currentParams,
    enable_search: isSearchModeChoose.value,
    isThinking: isThinking.value // 同时更新Think状态
  });
};

const clickThink = () => {
  // 切换思考状态
  isThinking.value = !isThinking.value;

  // 如果选择了Think模式，取消搜索模式（互斥）
  if (isThinking.value && isSearchModeChoose.value) {
    isSearchModeChoose.value = false;
  }

  // 更新aiChatStore中的Think状态
  const currentParams = aiChatStore.getAIChatParams() || {};
  aiChatStore.setAIChatParams({
    ...currentParams,
    isThinking: isThinking.value,
    enable_search: isSearchModeChoose.value, // 同时更新搜索状态
  });
};

const clickSend = () => {
  if (props.isSend) return;
  if (senderValue.value.trim()) {
    // 设置加载状态为true
    isLoading.value = true;

    // 获取当前所有选择的参数
    const params = getCurrentSelectParams();

    // 发送消息事件，将参数传递给父组件
    emit("onSend", params);

    // 清空输入框
    senderValue.value = "";
  }
};

const clickSendStop = () => {
  // 停止发送，设置加载状态为false
  isLoading.value = false;

  // 通知父组件停止事件
  emit("onSendStop");
};

const toggleModelSelector = () => {
  isModelSelectorOpen.value = !isModelSelectorOpen.value;
};

// 获取当前的所有选择参数
const getCurrentSelectParams = () => {
  return {
    isThinking: isThinking.value,
    content: senderValue.value,
    files: uploadFiles.value.filter((file) => !file.isLoading), // 只发送已上传完成的文件
    model: currentModel.value, // 使用当前模型名称
    enable_search: isSearchModeChoose.value, // 添加DeepSearch启用标识
  };
};

// 新的模型选择事件处理
const onModelSelected = (modelName) => {
  currentModel.value = modelName;

  // 更新aiChatStore中的模型信息
  const currentParams = aiChatStore.getAIChatParams() || {};
  aiChatStore.setAIChatParams({
    ...currentParams,
    model: modelName
  });
};

// 保持向后兼容的change事件处理（如果需要）
const onHandleChange = (index) => {
  // 这个方法现在主要用于向后兼容，实际的模型选择通过onModelSelected处理
  console.log('Model changed at index:', index);
};

// 附件按钮点击事件
const clickAttachFile = (event) => {
  // 防止触发下拉菜单关闭
  event.stopPropagation();
};

const onInputSubmit = () => {
  clickSend();
};

onBeforeMount(() => {
   // 如果有初始模型，设置当前模型
   if (props.initialModel) {
    currentModel.value = props.initialModel;
  }
  // 设置初始Think状态
  if (props.initialThinking) {
    isThinking.value = props.initialThinking;
  }
  // 设置初始搜索状态
  if (props.initialEnableSearch) {
    isSearchModeChoose.value = true;
  }
});



onMounted(() => {
  if (uploadFiles.value.length > 0) {
    senderRef.value.openHeader();
  }
});

// 监听文件上传列表变化，控制header显示
watch(
  () => uploadFiles.value,
  (newVal) => {
    if (newVal.length > 0) {
      senderRef.value.openHeader();
    } else {
      senderRef.value.closeHeader();
    }
  },
  { deep: true }
);

// 监听initialThinking prop变化
watch(
  () => props.initialThinking,
  (newVal) => {
    isThinking.value = newVal;
  }
);

// 监听initialEnableSearch prop变化
watch(
  () => props.initialEnableSearch,
  (newVal) => {
    isSearchModeChoose.value = newVal;
  }
);

defineExpose({
